function computeCashflowProjection(){const e=yalcaGroupTransactionsByMonth(SHELL_DATA.transactions),a=new Date,t=`${a.getFullYear()}-${String(a.getMonth()+1).padStart(2,"0")}`,n=e.length>0?e[e.length-1].key:t;let l=0;if(e.length>0){const a=e.length>1?e[e.length-2]:e[e.length-1];l=a.receita-a.despesa}let o=SHELL_DATA.settings.cashBalance;const r=[];let[d,c]=n.split("-").map(Number);for(let e=0;e<3;e++){c+=1,c>12&&(c=1,d+=1);const e=`${d}-${String(c).padStart(2,"0")}`,a=SHELL_DATA.plannedEntries.filter(a=>a.date.startsWith(e)).reduce((e,a)=>e+Number(a.amount),0);o=o+l+a,r.push({key:e,saldo:o,plannedForMonth:a})}return{recurringNet:l,projection:r,currentBalance:SHELL_DATA.settings.cashBalance,currentKey:n}}function renderFluxoCaixa(){const{recurringNet:e,projection:a,currentBalance:t,currentKey:n}=computeCashflowProjection(),l=a.reduce((e,a)=>a.saldo<e.saldo?a:e,a[0]);renderKpiGrid("cashflowKpis",[{label:"Saldo atual em caixa",value:yalcaFormatCurrency(t),delta:null,hint:yalcaMonthLabel(n+"-01"),info:"Saldo em caixa cadastrado nas Configurações, referente ao último mês com lançamentos fechados."},{label:"Lucro recorrente/mês",value:yalcaFormatCurrency(e),delta:null,hint:"baseado no último mês fechado",info:"Receita menos despesa do último mês totalmente fechado — usado como base pra projetar os próximos meses, assumindo que o ritmo se mantém."},{label:`Saldo projetado (${yalcaMonthLabel(a[2].key+"-01")})`,value:yalcaFormatCurrency(a[2].saldo),delta:null,info:"Estimativa de saldo em caixa daqui a 3 meses, somando o lucro recorrente mensal e os lançamentos futuros já cadastrados na tabela abaixo."},{label:"Mês mais apertado",value:yalcaMonthLabel(l.key+"-01"),delta:null,hint:yalcaFormatCurrency(l.saldo),info:"Dos próximos 3 meses projetados, qual deles tem o menor saldo em caixa estimado — útil pra se planejar com antecedência."}]);const o=[{label:yalcaMonthLabel(n+"-01"),value:t},...a.map(e=>({label:yalcaMonthLabel(e.key+"-01"),value:e.saldo}))];yalcaRenderLineChart(document.getElementById("cashflowChart"),{series:[{name:"Saldo projetado",color:YALCA_COLORS.series3,data:o}],formatValue:e=>yalcaFormatCurrency(e)}),renderPlannedTable()}function renderPlannedTable(){const e=document.getElementById("plannedTableBody"),a=[...SHELL_DATA.plannedEntries].sort((e,a)=>e.date.localeCompare(a.date));0!==a.length?e.innerHTML=a.map(e=>`\n    <tr>\n      <td>${yalcaFormatDate(e.date)}</td>\n      <td>${yalcaEscapeHtml(e.description)}</td>\n      <td class="num ${e.amount>=0?"text-good":"text-critical"}">${e.amount>=0?"+":""}${yalcaFormatCurrency(e.amount)}</td>\n      <td class="row-actions"><button class="icon-btn" title="Excluir" data-action="deletePlannedRow" data-id="${e.id}">🗑</button></td>\n    </tr>`).join(""):e.innerHTML='<tr><td colspan="4" class="alert-empty">Nenhum lançamento futuro cadastrado.</td></tr>'}async function deletePlannedRow(e){if(confirm("Excluir este lançamento futuro?"))try{await yalcaDeletePlannedEntry(e),SHELL_DATA=await yalcaFetchAll(YALCA_PROFILE),renderFluxoCaixa()}catch(e){alert("Não foi possível excluir: "+e.message)}}document.addEventListener("DOMContentLoaded",async()=>{await yalcaInitPortalShell()&&(renderFluxoCaixa(),document.getElementById("plannedTableBody").addEventListener("click",e=>{const a=e.target.closest('[data-action="deletePlannedRow"]');a&&deletePlannedRow(a.dataset.id)}),document.getElementById("addPlannedBtn").addEventListener("click",()=>{document.getElementById("plannedForm").reset(),openModal("plannedModal")}),document.getElementById("plannedForm").addEventListener("submit",async e=>{e.preventDefault();const a=e.target.querySelector('button[type="submit"]'),t={date:document.getElementById("plDate").value,description:document.getElementById("plDescription").value,amount:parseFloat(document.getElementById("plAmount").value)||0};a.disabled=!0,a.textContent="Salvando...";try{await yalcaAddPlannedEntry(t),closeModal("plannedModal"),SHELL_DATA=await yalcaFetchAll(YALCA_PROFILE),renderFluxoCaixa()}catch(e){alert("Não foi possível salvar: "+e.message)}finally{a.disabled=!1,a.textContent="Salvar"}}))});